use crate::app_error::AppError;
use sha2::{Digest, Sha256};
use std::fmt::Write;
use std::fs;
use std::path::Path;

/// Thumbnail engine descriptor used to disambiguate cache entries
/// generated by different engines or policy versions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ThumbnailEngine {
    /// Standard Rust `image` crate thumbnail path (images <= 100 MP).
    RustImage,
    /// Over the pixel budget (> 100 MP): no preview is generated.
    Oversized,
}

impl ThumbnailEngine {
    fn descriptor_tag(&self) -> &'static str {
        match self {
            ThumbnailEngine::RustImage => "rust-image",
            ThumbnailEngine::Oversized => "oversized",
        }
    }
}

/// Current cache version. Bump when algorithm, engine selection logic,
/// or output format changes in a way that invalidates prior thumbnails.
const CACHE_VERSION: &str = "v2";

/// Current pixel policy version. Bump when the pixel threshold
/// for engine routing changes.
const PIXEL_POLICY: &str = "100mp-v1";

/// Cache directory name derived from the current version.
pub fn cache_dir_version() -> &'static str {
    CACHE_VERSION
}

pub fn generate_cache_key(
    path: &Path,
    size: u32,
    engine: ThumbnailEngine,
    _cache_key_hint: Option<&str>,
) -> Result<String, AppError> {
    let metadata = fs::metadata(path)
        .map_err(|e| AppError::Io(format!("Failed to read metadata for cache key: {}", e)))?;

    let canonical_path = fs::canonicalize(path)
        .map_err(|e| AppError::Io(format!("Failed to canonicalize path for cache key: {}", e)))?;

    let file_size = metadata.len();

    let mtime = metadata
        .modified()
        .map(|t: std::time::SystemTime| {
            t.duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis()
        })
        .unwrap_or(0);

    let descriptor = format!(
        "{}|{}|{}|{}|{}|engine={}|pixel_policy={}",
        canonical_path.to_string_lossy(),
        file_size,
        mtime,
        size,
        CACHE_VERSION,
        engine.descriptor_tag(),
        PIXEL_POLICY,
    );

    let mut hasher = Sha256::new();
    hasher.update(descriptor.as_bytes());
    let hash = hasher.finalize();

    let mut hex_string = String::with_capacity(64);
    for byte in hash {
        write!(&mut hex_string, "{:02x}", byte).unwrap();
    }

    Ok(hex_string)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::NamedTempFile;

    fn create_temp_file() -> NamedTempFile {
        NamedTempFile::new().unwrap()
    }

    #[test]
    fn cache_key_differs_by_engine() {
        let f = create_temp_file();
        let key_rust = generate_cache_key(f.path(), 256, ThumbnailEngine::RustImage, None).unwrap();
        let key_big = generate_cache_key(f.path(), 256, ThumbnailEngine::Oversized, None).unwrap();
        assert_ne!(
            key_rust, key_big,
            "Different engines must produce different cache keys"
        );
    }

    #[test]
    fn cache_key_differs_by_size() {
        let f = create_temp_file();
        let key_a = generate_cache_key(f.path(), 200, ThumbnailEngine::RustImage, None).unwrap();
        let key_b = generate_cache_key(f.path(), 256, ThumbnailEngine::RustImage, None).unwrap();
        assert_ne!(key_a, key_b);
    }

    #[test]
    fn cache_key_deterministic() {
        let f = create_temp_file();
        let key1 = generate_cache_key(f.path(), 256, ThumbnailEngine::RustImage, None).unwrap();
        let key2 = generate_cache_key(f.path(), 256, ThumbnailEngine::RustImage, None).unwrap();
        assert_eq!(key1, key2, "Same inputs must produce same cache key");
    }
}
